import React, { useContext } from "react";
import {  CartContext } from "../context/cartContext";
import { graphql, Link } from "gatsby";
import Layout from "../components/layout";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { useTranslation } from "gatsby-plugin-react-i18next";

const CartPage = () => {
    const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }
  const userData: UserProfile = data;

  const { cart, removeFromCart, clearCart, decreaseQuantity, increaseQuantity } = cartContext;

  // Calculate the total number of items in the cart
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  // Calculate the total price of the cart
  const totalPrice = cart.reduce(
    (sum, item) => sum + item.price * item.quantity,
    0
  );

  return (
    <Layout data={userData}>
      <div className="container mx-auto p-4">
        {/* Header to go back to the products page */}
        <div className="flex justify-between items-center mb-4">
          <h1 className="text-2xl font-bold">{t("cart.ShoppingCart")}</h1>
          <Link to="/" className="bg-gray-800 text-white px-4 py-2 rounded">
            ⬅ {t("cart.backToProducts")}
          </Link>
        </div>

        {/* Show the cart items */}
        {cart.length === 0 ? (
          <p className="text-center text-gray-600">{t("cart.cartIsEmpty")}</p>
        ) : (
          <div className="space-y-4">
            {cart.map((item) => (
              <div
                key={item.id}
                className="border p-4 rounded-lg flex justify-between items-center"
              >
                <div>
                  <h2 className="text-lg font-semibold">{item.name}</h2>
                  <p className="text-gray-600">
                    ${item.price} x {item.quantity}
                  </p>
                </div>
                <div className="flex items-center gap-4">
                  <span className="font-bold text-xl">
                    {t("cart.total")}: ${item.price * item.quantity}
                  </span>

                  <div className="flex items-center gap-2">
                    <button
                      className="bg-red-500 text-white px-3 py-1 rounded disabled:opacity-50"
                      onClick={() => decreaseQuantity(item.id)}
                      disabled={item.quantity <= 0} // Disable if quantity is 0
                    >
                      -
                    </button>
                    <span>{item.quantity}</span>
                    <button
                      className="bg-green-500 text-white px-3 py-1 rounded disabled:opacity-50"
                      onClick={() => increaseQuantity(item.id)}
                      disabled={item.quantity >= 20} // Disable if quantity is 20
                    >
                      +
                    </button>
                  </div>

                  <button
                    className="bg-red-500 text-white px-4 py-2 rounded"
                    onClick={() => removeFromCart(item.id)}
                  >
                    {t("cart.remove")}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Total items */}
        <div className="mt-4 text-right font-bold text-lg">
          {t("cart.totalItems")}: {totalItems}
        </div>

        {/* Total price */}
        <div className="mt-2 text-right font-bold text-xl">
        {t("cart.totalPrice")}: ${totalPrice.toFixed(2)}
        </div>

        {/* Button to clear the cart */}
        {cart.length > 0 && (
          <div className="mt-4 text-right">
            <button
              className="bg-red-600 text-white px-6 py-2 rounded"
              onClick={clearCart}
            >
              {t("cart.emptyCart")}
            </button>
          </div>
        )}
      </div>

      <Link to="/checkout" className="bg-gray-800 text-white px-4 py-2 rounded w-full">
      {t("cart.checkout")}
          </Link>
    </Layout>
  );
};

export default CartPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
